ay_name\":\"Slovenčina (Slovak)\",\"language_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/18/26/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/18/26/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/18/26/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/18/\",\"title\":\"Chapter Eighteen: Conclusion – The Perfection of Renunciation\"}],\"url_path\":\"/en/library/bg/18/26/\",\"bb\":4019,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/18/25/\",\"title\":\"TEXT 25\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/18/27/\",\"title\":\"TEXT 27\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":4585,\"bb\":568492,\"url_path\":\"/en/library/bg/18/26/devanagari/\",\"body_final\":\"मुक्तसङ्गोऽनहंवादी धृत्युत्साहसमन्वित: ।
सिद्ध्यसिद्ध्योर्निर्विकार: कर्ता सात्त्विक उच्यते ॥ २६ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":4586,\"bb\":4020,\"url_path\":\"/en/library/bg/18/26/b4020/\",\"body_value\":\"mukta-saṅgo ’nahaṁ-vādī
dhṛty-utsāha-samanvitaḥ
siddhy-asiddhyor nirvikāraḥ
kartā sāttvika ucyate\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":4587,\"bb\":4021,\"url_path\":\"/en/library/bg/18/26/b4021/\",\"shadow_value\":\"mukta-saṅgaḥ – liberated from all material association; anaham-vādī – without false ego; dhṛti – with determination; utsāha – and great enthusiasm; samanvitaḥ – qualified; siddhi – in perfection; asiddhyoḥ – and failure; nirvikāraḥ – without change; kartā – worker; sāttvikaḥ – in the mode of goodness; ucyate – is said to be.\",\"word_for_word_value\":[{\"word\":\"mukta-saṅgaḥ\",\"translation\":\"liberated from all material association\"},{\"word\":\"anaham-vādī\",\"translation\":\"without false ego\"},{\"word\":\"dhṛti\",\"translation\":\"with determination\"},{\"word\":\"utsāha\",\"translation\":\"and great enthusiasm\"},{\"word\":\"samanvitaḥ\",\"translation\":\"qualified\"},{\"word\":\"siddhi\",\"translation\":\"in perfection\"},{\"word\":\"asiddhyoḥ\",\"translation\":\"and failure\"},{\"word\":\"nirvikāraḥ\",\"translation\":\"without change\"},{\"word\":\"kartā\",\"translation\":\"worker\"},{\"word\":\"sāttvikaḥ\",\"translation\":\"in the mode of goodness\"},{\"word\":\"ucyate\",\"translation\":\"is said to be\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":4588,\"bb\":4022,\"url_path\":\"/en/library/bg/18/26/b4022/\",\"body_value\":\"One who performs his duty without association with the modes of material nature, without false ego, with great determination and enthusiasm, and without wavering in success or failure is said to be a worker in the mode of goodness.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4589,\"bb\":4023,\"url_path\":\"/en/library/bg/18/26/b4023/\",\"body_value\":\"A person in Kṛṣṇa consciousness is always transcendental to the material modes of nature. He has no expectations for the result of the work entrusted to him, because he is above false ego and pride. Still, he is always enthusiastic till the completion of such work. He does not worry about the distress undertaken; he is always enthusiastic. He does not care for success or failure; he is equal in both distress and happiness. Such a worker is situated in the mode of goodness.\"}]}],\"short_title\":\"Bg. 18.26\",\"medium_title\":\"Bhagavad-gītā As It Is 18.26\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L25\",\"$L26\",\"$L27\"]}]\n"])self.__next_f.push([1,"29:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n2f:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n25:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/\",\"className\":\"text-vb-link\",\"children\":\"Library\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",nul